// Generated by Qleany v1.8.0 from feature_use_case.tera
// Custom implementation (hand-maintained — do NOT blanket-regenerate): upsert today's
// ProgressSnapshot on the open WorkInfo. `day` is truncated to UTC midnight, so a day
// already recorded is replaced (idempotent — a save and an app-open on the same day don't
// pile up rows). Short synchronous command, `undoable: false` (telemetry, not authored
// content — never enters the undo history).
use crate::RecordProgressSnapshotDto;
use anyhow::{Result, anyhow};
use chrono::{DateTime, Utc};
use common::database::CommandUnitOfWork;
use common::direct_access::work_info::WorkInfoRelationshipField;
use common::entities::{ProgressSnapshot, WorkInfo};
use common::types::EntityId;

pub trait RecordProgressSnapshotUnitOfWorkFactoryTrait: Send + Sync {
    fn create(&self) -> Box<dyn RecordProgressSnapshotUnitOfWorkTrait>;
}

// Read-write unit of work. The identical macro set must appear on the impl in
// ../units_of_work/record_progress_snapshot_uow.rs. No Snapshot/Restore — ProgressSnapshot
// is `undoable: false`, so this never touches the undo stack.
#[macros::uow_action(entity = "WorkInfo", action = "GetAll")]
#[macros::uow_action(entity = "WorkInfo", action = "GetRelationship")]
#[macros::uow_action(entity = "WorkInfo", action = "SetRelationship")]
#[macros::uow_action(entity = "ProgressSnapshot", action = "GetMulti")]
#[macros::uow_action(entity = "ProgressSnapshot", action = "CreateOrphan")]
#[macros::uow_action(entity = "ProgressSnapshot", action = "RemoveMulti")]
pub trait RecordProgressSnapshotUnitOfWorkTrait: CommandUnitOfWork {
    fn publish_record_progress_snapshot_event(&self, ids: Vec<EntityId>, data: Option<String>);
}

/// Midnight-UTC of the given instant — the stable per-day key.
fn truncate_to_day(dt: DateTime<Utc>) -> DateTime<Utc> {
    dt.date_naive()
        .and_hms_opt(0, 0, 0)
        .expect("midnight is a valid time")
        .and_utc()
}

pub struct RecordProgressSnapshotUseCase {
    uow_factory: Box<dyn RecordProgressSnapshotUnitOfWorkFactoryTrait>,
}

impl RecordProgressSnapshotUseCase {
    pub fn new(uow_factory: Box<dyn RecordProgressSnapshotUnitOfWorkFactoryTrait>) -> Self {
        RecordProgressSnapshotUseCase { uow_factory }
    }

    pub fn execute(&mut self, dto: &RecordProgressSnapshotDto) -> Result<()> {
        let mut uow = self.uow_factory.create();
        uow.begin_transaction()?;

        let result = self.run(&*uow, dto);
        match result {
            Ok(work_info_id) => {
                uow.commit()?;
                uow.publish_record_progress_snapshot_event(vec![work_info_id], None);
                Ok(())
            }
            Err(e) => {
                let _ = uow.rollback();
                Err(e)
            }
        }
    }

    fn run(
        &self,
        uow: &dyn RecordProgressSnapshotUnitOfWorkTrait,
        dto: &RecordProgressSnapshotDto,
    ) -> Result<EntityId> {
        // Record onto the caller-named Work's own WorkInfo, found via its
        // `WorkInfo.work` back-pointer.
        let work_id = dto.work_id as EntityId;
        let work_info: WorkInfo = uow
            .get_all_work_info()?
            .into_iter()
            .find(|wi| wi.work == Some(work_id))
            .ok_or_else(|| anyhow!("work {work_id} is not open"))?;

        let existing_ids = uow.get_work_info_relationship(
            &work_info.id,
            &WorkInfoRelationshipField::ProgressSnapshots,
        )?;
        let existing: Vec<ProgressSnapshot> = uow
            .get_progress_snapshot_multi(&existing_ids)?
            .into_iter()
            .flatten()
            .collect();

        let day_key = truncate_to_day(dto.day);

        // Keep every other day; every row for today (there should be one, but a corrupted
        // or hand-edited history could hold several) is replaced by the fresh one.
        let mut kept_ids: Vec<EntityId> = Vec::new();
        let mut replaced: Vec<EntityId> = Vec::new();
        for s in &existing {
            if truncate_to_day(s.day) == day_key {
                replaced.push(s.id);
            } else {
                kept_ids.push(s.id);
            }
        }

        // `created_at`/`updated_at` must be set explicitly: `DateTime<Utc>::default()` is
        // the Unix epoch, not "now", so letting `..Default::default()` cover them would
        // stamp every snapshot 1970-01-01 — and both fields are persisted into the bundle
        // by `ProgressSnapshotFile`.
        let now = chrono::Utc::now();
        let created = uow.create_orphan_progress_snapshot(&ProgressSnapshot {
            created_at: now,
            updated_at: now,
            day: day_key,
            total_word_count: dto.total_word_count,
            total_char_count: Some(dto.total_char_count),
            book_item_ids: dto.book_item_ids.clone(),
            book_word_counts: dto.book_word_counts.clone(),
            ..Default::default()
        })?;
        kept_ids.push(created.id);

        // Point WorkInfo at the new set FIRST (drops the old rows from the junction), then
        // free the replaced entities so no dangling id or orphan remains.
        uow.set_work_info_relationship(
            &work_info.id,
            &WorkInfoRelationshipField::ProgressSnapshots,
            &kept_ids,
        )?;
        if !replaced.is_empty() {
            uow.remove_progress_snapshot_multi(&replaced)?;
        }

        Ok(work_info.id)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn truncate_to_day_collapses_times_within_a_day_and_separates_days() {
        let morning = DateTime::parse_from_rfc3339("2020-05-01T08:30:00+00:00")
            .unwrap()
            .with_timezone(&Utc);
        let evening = DateTime::parse_from_rfc3339("2020-05-01T23:59:59+00:00")
            .unwrap()
            .with_timezone(&Utc);
        let next_day = DateTime::parse_from_rfc3339("2020-05-02T00:00:01+00:00")
            .unwrap()
            .with_timezone(&Utc);

        assert_eq!(truncate_to_day(morning), truncate_to_day(evening));
        assert_ne!(truncate_to_day(morning), truncate_to_day(next_day));
        // The key is midnight UTC.
        assert_eq!(
            truncate_to_day(evening).to_rfc3339(),
            "2020-05-01T00:00:00+00:00"
        );
    }
}
